import * as React from "react"
import { addPropertyControls, ControlType } from "framer"

/**
 * Beat Pad Sampler
 * -----------------
 * A 4x4 grid of numbered pads styled after a hardware sampler unit.
 *
 * Held-on pads work as a volume gate: the first time a pad is tapped, its
 * track starts looping in the background at silence (gain 0), locked to a
 * single shared timeline. Tapping it again just ramps its own gain between
 * 0 and 1 — the track itself never stops or restarts, so every held-on pad
 * stays sample-accurately in phase with every other one, no matter what
 * order they're tapped in or how long between taps.
 *
 * Tap-mode pads are unrelated one-shot triggers: they play once through
 * and reset automatically when finished.
 *
 * The line at the bottom drives an ambient backlight glow behind the
 * whole unit, and doubles as the glow color for any pad that's active.
 *
 * IMPORTANT: for held-on pads to stay musically in phase with each other
 * (not just sample-locked to the same timeline), upload loops that are
 * already tempo-matched and the same length (e.g. all loops are exactly
 * 2 bars long at 120 BPM) — mismatched lengths will still play in perfect
 * sync relative to the shared clock, but can drift out of phase with each
 * other musically over time.
 */

type PadMode = "toggle" | "tap"

interface PadConfig {
    label: string
    audio?: string
    mode?: PadMode
    maxVolume?: number
}

type Layout = "vertical" | "horizontal"
type LogoAlign = "left" | "center" | "right"

interface LogoWord {
    text: string
    // 0 means "inherit the shared Logo Size / Logo Weight controls" —
    // lets most words stay on the shared default while individual words
    // are dialed in on their own
    fontSize: number
    fontWeight: number
}
type FramerImage = string | { src: string }

interface BeatPadSamplerProps {
    pads: PadConfig[]
    instrumentPads: PadConfig[]
    bpm: number
    barsPerLoop: number
    defaultHue: number
    showHueSlider: boolean
    glowSize: number
    screenLabel: string
    layout: Layout
    showLogo: boolean
    logoWords: LogoWord[]
    logoAlign: LogoAlign
    logoFontSize: number
    logoFontWeight: number
    logoLetterSpacing: number
    logoColor: string
    backgroundColor?: string
    backgroundImage?: FramerImage
    textureImage?: FramerImage
    textureOpacity: number
    textureColor: string
    textureScale: number
    faceplateTexture?: FramerImage
    defaultFaceplateTexture?: FramerImage
    faceplateColor?: string
    padTextureImage?: FramerImage
    padTextureOpacity: number
    padDefaultColor: string
    defaultWoodFaceplate?: boolean
    glassOpacity: number
    style?: React.CSSProperties
}

function imageSrc(image?: FramerImage): string | undefined {
    if (!image) return undefined
    return typeof image === "string" ? image : image.src
}

const GRID_SIZE = 16
const INSTRUMENT_GRID_SIZE = 16
// well clear of the main grid's 0-15 index range, so instrument pads can
// share all the same tap-trigger state/refs (sourcesRef, activeState,
// etc. — all just plain numeric-keyed maps) without ever colliding with
// a main pad's index
const INSTRUMENT_INDEX_OFFSET = 1000
const INSTRUMENT_FLASH_DURATION_MS = 150
const MOBILE_BREAKPOINT = 640
const TABLET_BREAKPOINT = 1199
const GRID_GAP = 8
const VIS_WIDTH = 60
const VIS_HEIGHT = 34
const WOOD_FACEPLATE_URL =
    "https://www.avino-timber.com/storage/images-processed/w-1200_h-auto_m-fit_s-any__Black-Walnut-Wood.jpg"
const FX_LOADER_GIF =
    "data:image/gif;base64,"
const DEFAULT_FACEPLATE_COLOR = "#202227"
const DEFAULT_APP_BACKGROUND_COLOR = "#050506"
const DEFAULT_LOGO_WORDS: LogoWord[] = [
    { text: "kinetic", fontSize: 0, fontWeight: 0 },
    { text: "groovebox", fontSize: 0, fontWeight: 0 },
]
const FX_CUTOFF_GIF =
    "data:image/gif;base64,"
const FX_ECHO_GIF =
    "data:image/gif;base64,"

const FX_FLANGER_GIF =
    "data:image/gif;base64,"

const FX_PHASER_GIF =
    "data:image/gif;base64,"

const FX_REVERB_GIF =
    "data:image/gif;base64,"

function clamp255(n: number): number {
    return Math.max(0, Math.min(255, Math.round(n)))
}

function parseColorToRgb(color: string): { r: number; g: number; b: number } {
    const c = color.trim()
    if (c.startsWith("#")) {
        const clean = c.slice(1)
        const full =
            clean.length === 3
                ? clean
                      .split("")
                      .map((ch) => ch + ch)
                      .join("")
                : clean
        const num = parseInt(full.slice(0, 6), 16)
        return { r: (num >> 16) & 255, g: (num >> 8) & 255, b: num & 255 }
    }
    const match = c.match(/rgba?\(([^)]+)\)/i)
    if (match) {
        const parts = match[1].split(",").map((p) => parseFloat(p.trim()))
        return { r: parts[0] ?? 0, g: parts[1] ?? 0, b: parts[2] ?? 0 }
    }
    return { r: 32, g: 34, b: 39 }
}

function shadeColor(color: string, amount: number): string {
    const { r, g, b } = parseColorToRgb(color)
    return `rgb(${clamp255(r + amount)}, ${clamp255(g + amount)}, ${clamp255(b + amount)})`
}

function faceplateGradient(color: string): string {
    return `linear-gradient(160deg, ${shadeColor(color, 11)} 0%, ${color} 60%, ${shadeColor(
        color,
        -12
    )} 100%)`
}

type FxKey = "echo" | "flanger" | "phaser" | "reverb"

const FX_WET_LEVELS: Record<FxKey, number> = {
    echo: 0.55,
    flanger: 0.65,
    phaser: 0.7,
    reverb: 0.5,
}

const FX_LABELS: Record<FxKey, string> = {
    echo: "Echo",
    flanger: "Flanger",
    phaser: "Phaser",
    reverb: "Reverb",
}

const FX_KNOB_GIFS: Record<FxKey, string> = {
    echo: FX_ECHO_GIF,
    flanger: FX_FLANGER_GIF,
    phaser: FX_PHASER_GIF,
    reverb: FX_REVERB_GIF,
}

// Max Volume is a 0-100 percentage from Framer's panel, but Web Audio
// gain is linear amplitude while human hearing perceives loudness on
// roughly a logarithmic (dB) scale — a plain percent/100 gain (e.g. 30%
// -> 0.3 linear, only about -10.5dB) reads as barely quieter than full
// volume. Squaring the ratio approximates the "audio taper" curve real
// mixers use, so the percentage tracks much closer to how loud it
// actually sounds (30% -> 0.09 linear, about -20.9dB — genuinely
// noticeably quieter).
function maxVolumeToGain(percent: number): number {
    const t = Math.max(0, Math.min(100, percent)) / 100
    return t * t
}

// classic CDJ-style color filter: centered = fully open (no audible
// effect), turning left sweeps a resonant low-pass down (cuts highs,
// muffled), turning right sweeps a resonant high-pass up (cuts bass, thin)
function applyFilterValue(filter: BiquadFilterNode, value: number) {
    const ctx = filter.context
    const now = ctx.currentTime
    if (value <= 0) {
        const t = Math.min(1, -value / 50)
        filter.type = "lowpass"
        const freq = 20000 * Math.pow(200 / 20000, t)
        filter.frequency.setTargetAtTime(freq, now, 0.02)
        filter.Q.setTargetAtTime(0.7 + t * 6, now, 0.02)
    } else {
        const t = Math.min(1, value / 50)
        filter.type = "highpass"
        const freq = 20 * Math.pow(4000 / 20, t)
        filter.frequency.setTargetAtTime(freq, now, 0.02)
        filter.Q.setTargetAtTime(0.7 + t * 6, now, 0.02)
    }
}

// synthesizes a decaying-noise impulse response so reverb doesn't need an
// external audio file
function createReverbImpulse(ctx: AudioContext): AudioBuffer {
    const duration = 2.2
    const decay = 3.2
    const length = Math.floor(ctx.sampleRate * duration)
    const impulse = ctx.createBuffer(2, length, ctx.sampleRate)
    for (let ch = 0; ch < 2; ch++) {
        const data = impulse.getChannelData(ch)
        for (let i = 0; i < length; i++) {
            data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay)
        }
    }
    return impulse
}

export default function BeatPadSampler(props: BeatPadSamplerProps) {
    const {
        pads = [],
        instrumentPads = [],
        bpm = 120,
        barsPerLoop = 2,
        defaultHue = 265,
        showHueSlider = true,
        glowSize = 40,
        screenLabel = "SAMPLER",
        layout = "vertical",
        showLogo = true,
        logoWords = DEFAULT_LOGO_WORDS,
        logoAlign = "center",
        logoFontSize = 15,
        logoFontWeight = 600,
        logoLetterSpacing = 0.5,
        logoColor = "#ffffff",
        backgroundColor = DEFAULT_APP_BACKGROUND_COLOR,
        backgroundImage,
        textureImage,
        textureOpacity = 35,
        textureColor = "#ffffff",
        textureScale = 10,
        faceplateTexture,
        defaultFaceplateTexture,
        faceplateColor = DEFAULT_FACEPLATE_COLOR,
        defaultWoodFaceplate = false,
        padTextureImage,
        padTextureOpacity = 30,
        padDefaultColor = "#35353b",
        glassOpacity = 45,
        style,
    } = props

    const isHorizontal = layout === "horizontal"
    const backgroundImageSrc = imageSrc(backgroundImage)
    const textureImageSrc = imageSrc(textureImage)
    const faceplateTextureSrc = imageSrc(faceplateTexture) ?? WOOD_FACEPLATE_URL
    const defaultFaceplateTextureSrc = imageSrc(defaultFaceplateTexture)
    const padTextureSrc = imageSrc(padTextureImage)

    const outerRef = React.useRef<HTMLDivElement | null>(null)
    const [isMobile, setIsMobile] = React.useState(false)
    const [isTablet, setIsTablet] = React.useState(false)

    React.useLayoutEffect(() => {
        const el = outerRef.current
        if (!el) return
        const measure = (width: number) => {
            setIsMobile(width > 0 && width <= MOBILE_BREAKPOINT)
            setIsTablet(width > MOBILE_BREAKPOINT && width <= TABLET_BREAKPOINT)
        }

        // set the initial classification synchronously — don't rely on the
        // observer's first callback, which some embedding contexts delay
        // or never fire until an actual layout change occurs
        measure(el.getBoundingClientRect().width)

        if (typeof ResizeObserver === "undefined") return
        const observer = new ResizeObserver((entries) => {
            const width = entries[0]?.contentRect.width ?? 0
            measure(width)
        })
        observer.observe(el)
        return () => observer.disconnect()
    }, [])

    // knobs/header get the larger, mobile-style treatment at both phone
    // and tablet widths; only the pad-grid sizing and outer body framing
    // (full-bleed vs. bounded card) stay phone-specific
    const useCompactHeader = isMobile || isTablet

    const gridWrapRef = React.useRef<HTMLDivElement | null>(null)
    const [mobileSquareSize, setMobileSquareSize] = React.useState<
        number | null
    >(null)

    React.useLayoutEffect(() => {
        if (!isMobile) {
            setMobileSquareSize(null)
            return
        }
        const el = gridWrapRef.current
        if (!el) return
        const cols = 4
        // sized from width alone (not height) so the grid's total width
        // always exactly fills its container — keeping its left/right
        // edges flush with the screen above, which spans that same width
        const measure = (width: number) => {
            const sizeFromWidth = (width - (cols - 1) * GRID_GAP) / cols
            setMobileSquareSize(Math.max(0, sizeFromWidth))
        }

        const rect = el.getBoundingClientRect()
        measure(rect.width)

        if (typeof ResizeObserver === "undefined") return
        const observer = new ResizeObserver((entries) => {
            const r = entries[0]?.contentRect
            if (r) measure(r.width)
        })
        observer.observe(el)
        return () => observer.disconnect()
    }, [isMobile])

    const [hue, setHue] = React.useState(defaultHue)
    React.useEffect(() => setHue(defaultHue), [defaultHue])

    // pressing "w" swaps the faceplate finish between dark grey and walnut
    // wood. Ignored while the user is typing in an editable field elsewhere
    // on the page, so the shortcut doesn't hijack normal text entry.
    //
    // Listens in the capture phase (the earliest point a keydown can be
    // observed, before any element's own bubble-phase handler gets a
    // chance to call stopPropagation() on it) so a host page's own scripts
    // — Framer's interaction/scroll runtime, another embedded widget, etc.
    // — can't silently swallow the key before it reaches us.
    const [woodFaceplate, setWoodFaceplate] =
        React.useState(defaultWoodFaceplate)
    React.useEffect(
        () => setWoodFaceplate(defaultWoodFaceplate),
        [defaultWoodFaceplate]
    )
    React.useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const isW = e.key?.toLowerCase() === "w" || e.code === "KeyW"
            if (!isW) return
            const target = e.target as HTMLElement | null
            const tag = target?.tagName
            if (
                tag === "INPUT" ||
                tag === "TEXTAREA" ||
                target?.isContentEditable
            ) {
                return
            }
            setWoodFaceplate((prev) => !prev)
        }
        window.addEventListener("keydown", handleKeyDown, true)
        return () => window.removeEventListener("keydown", handleKeyDown, true)
    }, [])

    const hueTrackRef = React.useRef<HTMLDivElement | null>(null)

    const updateHueFromClientX = React.useCallback((clientX: number) => {
        const el = hueTrackRef.current
        if (!el) return
        const rect = el.getBoundingClientRect()
        const frac = Math.min(
            1,
            Math.max(0, (clientX - rect.left) / rect.width)
        )
        setHue(Math.round(frac * 360))
    }, [])

    const handleHuePointerDown = React.useCallback(
        (e: React.PointerEvent<HTMLDivElement>) => {
            try {
                e.currentTarget.setPointerCapture(e.pointerId)
            } catch (err) {
                // no active pointer session to capture; safe to ignore
            }
            updateHueFromClientX(e.clientX)
        },
        [updateHueFromClientX]
    )

    const handleHuePointerMove = React.useCallback(
        (e: React.PointerEvent<HTMLDivElement>) => {
            if (e.buttons !== 1) return
            updateHueFromClientX(e.clientX)
        },
        [updateHueFromClientX]
    )

    const [activeState, setActiveState] = React.useState<
        Record<number, "queued" | "playing">
    >({})

    const ctxRef = React.useRef<AudioContext | null>(null)
    const buffersRef = React.useRef<Map<number, AudioBuffer>>(new Map())
    // tap-mode (one-shot) pads only
    const sourcesRef = React.useRef<Map<number, AudioBufferSourceNode>>(
        new Map()
    )
    const timeoutsRef = React.useRef<Map<number, number>>(new Map())
    const tapRequestRef = React.useRef<Map<number, symbol>>(new Map())
    const masterGainRef = React.useRef<GainNode | null>(null)
    const analyserRef = React.useRef<AnalyserNode | null>(null)
    const visCanvasRef = React.useRef<HTMLCanvasElement | null>(null)
    const rafRef = React.useRef<number | null>(null)

    // held-on (toggle-mode) pads: each track starts once, the first time
    // it's engaged, and keeps looping forever from that shared start point.
    // Tapping a pad never starts/stops audio — it only ramps that pad's own
    // gain between 0 and 1, so every held-on track stays sample-accurately
    // in phase with every other one regardless of tap order or timing.
    const masterStartRef = React.useRef<number | null>(null)
    const toggleGainsRef = React.useRef<Map<number, GainNode>>(new Map())
    const toggleSourcesRef = React.useRef<Map<number, AudioBufferSourceNode>>(
        new Map()
    )

    // master FX chain: masterGain -> filter (series insert) -> fxBus, with
    // echo/flanger/phaser/reverb wired as parallel sends off the filtered
    // signal, each mixed back into fxBus through its own wet gain. Filter
    // has to be a true series insert (it needs to actually remove
    // frequencies); the other four are always-on sends whose wet level is
    // just ramped between 0 and an audible mix, which avoids any graph
    // rewiring (and the clicks that come with it) when toggling them.
    const filterNodeRef = React.useRef<BiquadFilterNode | null>(null)
    const fxWetGainsRef = React.useRef<Record<FxKey, GainNode | null>>({
        echo: null,
        flanger: null,
        phaser: null,
        reverb: null,
    })
    const echoDelayRef = React.useRef<DelayNode | null>(null)

    // each knob (the 4 FX sends plus the cutoff filter) is a continuous
    // bipolar value (-50..50, 0 = neutral/off) adjusted by vertical
    // click-drag like a real plugin knob. lastTouchedParam drives the
    // digital readout: it shows whichever knob was most recently grabbed.
    const [fxValues, setFxValues] = React.useState<Record<FxKey, number>>({
        echo: 0,
        flanger: 0,
        phaser: 0,
        reverb: 0,
    })
    const [cutoffValue, setCutoffValue] = React.useState(0)
    const [isDraggingCutoff, setIsDraggingCutoff] = React.useState(false)
    const [draggingFxKey, setDraggingFxKey] = React.useState<FxKey | null>(null)
    const [lastTouchedParam, setLastTouchedParam] = React.useState<
        FxKey | "cutoff" | null
    >(null)
    const knobDragRef = React.useRef<{
        key: FxKey
        startY: number
        startValue: number
    } | null>(null)
    const cutoffDragRef = React.useRef<{
        startY: number
        startValue: number
    } | null>(null)

    const gridPads: PadConfig[] = React.useMemo(() => {
        return Array.from(
            { length: GRID_SIZE },
            (_, i) => pads[i] ?? { label: "", audio: undefined }
        )
    }, [pads])

    const instrumentGridPads: PadConfig[] = React.useMemo(() => {
        return Array.from(
            { length: INSTRUMENT_GRID_SIZE },
            (_, i) => instrumentPads[i] ?? { label: "", audio: undefined }
        )
    }, [instrumentPads])

    const getContext = React.useCallback(() => {
        if (!ctxRef.current) {
            const AC = window.AudioContext || (window as any).webkitAudioContext
            const ctx = new AC()
            const gain = ctx.createGain()
            const analyser = ctx.createAnalyser()
            analyser.fftSize = 64
            analyser.smoothingTimeConstant = 0.72

            // series insert: everything passes through the filter, neutral
            // (fully open) until the knob is moved
            const filter = ctx.createBiquadFilter()
            applyFilterValue(filter, 0)
            const fxBus = ctx.createGain()
            gain.connect(filter)
            filter.connect(fxBus) // dry path
            fxBus.connect(analyser)
            analyser.connect(ctx.destination)

            // echo: delay + internal feedback loop, sent to fxBus through
            // its own wet gain (starts silent until toggled on)
            const echoDelay = ctx.createDelay(2)
            echoDelay.delayTime.value = Math.max(0.05, 60 / bpm / 2)
            const echoFeedback = ctx.createGain()
            echoFeedback.gain.value = 0.35
            const echoWet = ctx.createGain()
            echoWet.gain.value = 0
            filter.connect(echoDelay)
            echoDelay.connect(echoFeedback)
            echoFeedback.connect(echoDelay)
            echoDelay.connect(echoWet)
            echoWet.connect(fxBus)

            // flanger: short modulated delay with feedback
            const flangerDelay = ctx.createDelay(0.05)
            flangerDelay.delayTime.value = 0.006
            const flangerLfo = ctx.createOscillator()
            flangerLfo.frequency.value = 0.25
            const flangerLfoGain = ctx.createGain()
            flangerLfoGain.gain.value = 0.003
            const flangerFeedback = ctx.createGain()
            flangerFeedback.gain.value = 0.3
            const flangerWet = ctx.createGain()
            flangerWet.gain.value = 0
            flangerLfo.connect(flangerLfoGain)
            flangerLfoGain.connect(flangerDelay.delayTime)
            filter.connect(flangerDelay)
            flangerDelay.connect(flangerFeedback)
            flangerFeedback.connect(flangerDelay)
            flangerDelay.connect(flangerWet)
            flangerWet.connect(fxBus)
            flangerLfo.start()

            // phaser: a few swept all-pass stages in series
            const phaserStages = Array.from({ length: 4 }, () => {
                const stage = ctx.createBiquadFilter()
                stage.type = "allpass"
                stage.frequency.value = 800
                return stage
            })
            const phaserLfo = ctx.createOscillator()
            phaserLfo.frequency.value = 0.3
            const phaserLfoGain = ctx.createGain()
            phaserLfoGain.gain.value = 700
            const phaserWet = ctx.createGain()
            phaserWet.gain.value = 0
            phaserLfo.connect(phaserLfoGain)
            phaserStages.forEach((stage) =>
                phaserLfoGain.connect(stage.frequency)
            )
            filter.connect(phaserStages[0])
            for (let i = 0; i < phaserStages.length - 1; i++) {
                phaserStages[i].connect(phaserStages[i + 1])
            }
            phaserStages[phaserStages.length - 1].connect(phaserWet)
            phaserWet.connect(fxBus)
            phaserLfo.start()

            // reverb: synthesized impulse response, no external file needed
            const convolver = ctx.createConvolver()
            convolver.buffer = createReverbImpulse(ctx)
            const reverbWet = ctx.createGain()
            reverbWet.gain.value = 0
            filter.connect(convolver)
            convolver.connect(reverbWet)
            reverbWet.connect(fxBus)

            ctxRef.current = ctx
            masterGainRef.current = gain
            analyserRef.current = analyser
            filterNodeRef.current = filter
            echoDelayRef.current = echoDelay
            fxWetGainsRef.current = {
                echo: echoWet,
                flanger: flangerWet,
                phaser: phaserWet,
                reverb: reverbWet,
            }
        }
        const ctx = ctxRef.current
        if (ctx.state === "suspended") {
            ctx.resume()
        }
        // iOS Safari only treats playback as "inside" the user gesture if a
        // source is started synchronously with it. Loading a pad's audio
        // requires an async fetch/decode first, which crosses that window
        // and can leave playback silently muted. Unlocking with a silent
        // buffer here — synchronously, on every tap — keeps the context
        // audible regardless of how long the actual sample takes to load.
        try {
            const unlockBuffer = ctx.createBuffer(1, 1, 22050)
            const unlockSource = ctx.createBufferSource()
            unlockSource.buffer = unlockBuffer
            unlockSource.connect(ctx.destination)
            unlockSource.start(0)
        } catch (e) {
            // best-effort unlock; safe to ignore if it fails
        }
        return ctx
    }, [bpm])

    const loadBuffer = React.useCallback(
        async (index: number, url: string) => {
            const ctx = getContext()
            const cached = buffersRef.current.get(index)
            if (cached) return cached
            const res = await fetch(url)
            const arrayBuffer = await res.arrayBuffer()
            const audioBuffer = await ctx.decodeAudioData(arrayBuffer)
            buffersRef.current.set(index, audioBuffer)
            return audioBuffer
        },
        [getContext]
    )

    const stopPad = React.useCallback((index: number) => {
        const src = sourcesRef.current.get(index)
        if (src) {
            try {
                src.stop()
            } catch (e) {
                // already stopped
            }
            sourcesRef.current.delete(index)
        }
        const t = timeoutsRef.current.get(index)
        if (t) {
            clearTimeout(t)
            timeoutsRef.current.delete(index)
        }
        setActiveState((prev) => {
            const next = { ...prev }
            delete next[index]
            return next
        })
    }, [])

    const triggerTapPad = React.useCallback(
        async (index: number, pad: PadConfig) => {
            if (!pad.audio) return
            const isInstrument = index >= INSTRUMENT_INDEX_OFFSET

            if (isInstrument) {
                // instrument pads always retrigger fresh on every tap,
                // cutting off whatever's still playing instead of toggling
                // it to a stop — rapid tapping needs to feel instantaneous,
                // like a real sample pad, not alternate between "hit" and
                // "cut off" on every other tap. stopPad() clears the old
                // voice immediately; canceling any pending tapRequestRef
                // reservation (from a tap whose buffer load hasn't
                // resolved yet) lets this tap's own request win instead.
                stopPad(index)
                tapRequestRef.current.delete(index)
            } else if (
                // tapping an already-playing (or about-to-play) main tap
                // pad stops it, instead of layering another retrigger on
                // top. A source only gets registered in sourcesRef *after*
                // the buffer has finished loading (below), so a truly
                // rapid double-tap can fire its second call while the
                // first is still mid-await, before sourcesRef has
                // anything to check against. The token reserved
                // synchronously just below closes that window: the second
                // call sees the pending reservation immediately and
                // cancels it, and the first call notices the cancellation
                // once its buffer load resolves and bails out before ever
                // starting playback.
                sourcesRef.current.has(index) ||
                tapRequestRef.current.has(index)
            ) {
                tapRequestRef.current.delete(index)
                stopPad(index)
                return
            }
            const requestToken = Symbol()
            tapRequestRef.current.set(index, requestToken)
            const ctx = getContext()
            let buffer: AudioBuffer
            try {
                buffer = await loadBuffer(index, pad.audio)
            } catch (e) {
                tapRequestRef.current.delete(index)
                return
            }
            if (tapRequestRef.current.get(index) !== requestToken) return
            tapRequestRef.current.delete(index)
            const now = ctx.currentTime
            const startAt = now + 0.02

            const source = ctx.createBufferSource()
            source.buffer = buffer
            source.loop = false

            const gain = ctx.createGain()
            gain.gain.value = maxVolumeToGain(pad.maxVolume ?? 100)
            source.connect(gain)
            gain.connect(masterGainRef.current!)

            // reset automatically once playback ends, but only if this
            // source is still the one tracked for this pad (a newer
            // retrigger may have already replaced it)
            source.onended = () => {
                if (sourcesRef.current.get(index) !== source) return
                sourcesRef.current.delete(index)
                setActiveState((prev) => {
                    if (!(index in prev)) return prev
                    const next = { ...prev }
                    delete next[index]
                    return next
                })
            }

            source.start(startAt)
            sourcesRef.current.set(index, source)

            // instrument pads flash lit only briefly on trigger instead of
            // staying lit for the sample's full length — sample-based
            // instrument sounds can run several seconds, which read as
            // "stuck on" rather than a tap response. Main tap pads keep
            // the original behavior (lit for the whole sample).
            setActiveState((prev) => ({ ...prev, [index]: "queued" }))
            const delayMs = Math.max(0, (startAt - now) * 1000)
            const timeoutId = window.setTimeout(() => {
                setActiveState((prev) =>
                    prev[index] ? { ...prev, [index]: "playing" } : prev
                )
                timeoutsRef.current.delete(index)
                if (isInstrument) {
                    const flashId = window.setTimeout(() => {
                        setActiveState((prev) => {
                            if (!(index in prev)) return prev
                            const next = { ...prev }
                            delete next[index]
                            return next
                        })
                        timeoutsRef.current.delete(index)
                    }, INSTRUMENT_FLASH_DURATION_MS)
                    timeoutsRef.current.set(index, flashId)
                }
            }, delayMs)
            timeoutsRef.current.set(index, timeoutId)
        },
        [stopPad, getContext, loadBuffer]
    )

    // starts a held-on pad's track the first time it's engaged, locked to
    // the shared masterStartRef timeline. If the track is being primed
    // later than that shared start (e.g. its buffer took longer to decode,
    // or it's simply the first time THIS pad has been tapped in the
    // session), it's started mid-buffer at the correct offset so it's
    // already in phase with everything else instead of restarting from 0.
    const primeToggleTrack = React.useCallback(
        async (index: number, url: string) => {
            const ctx = getContext()
            if (masterStartRef.current === null) {
                masterStartRef.current = ctx.currentTime + 0.15
            }
            const startAt = masterStartRef.current

            let buffer: AudioBuffer
            try {
                buffer = await loadBuffer(index, url)
            } catch (e) {
                return
            }
            if (toggleSourcesRef.current.has(index)) return

            const gain = ctx.createGain()
            gain.gain.value = 0
            gain.connect(masterGainRef.current!)

            const source = ctx.createBufferSource()
            source.buffer = buffer
            source.loop = true
            source.connect(gain)

            const now = ctx.currentTime
            if (now < startAt) {
                source.start(startAt)
            } else {
                const offset = (now - startAt) % buffer.duration
                source.start(now, offset)
            }

            toggleGainsRef.current.set(index, gain)
            toggleSourcesRef.current.set(index, source)
        },
        [getContext, loadBuffer]
    )

    const togglePad = React.useCallback(
        async (index: number) => {
            const pad = gridPads[index]
            if (!pad.audio) return
            const turningOn = !activeState[index]

            if (!toggleGainsRef.current.has(index)) {
                await primeToggleTrack(index, pad.audio)
            }
            const gain = toggleGainsRef.current.get(index)
            if (!gain) return
            const maxVolume = maxVolumeToGain(pad.maxVolume ?? 100)
            gain.gain.value = turningOn ? maxVolume : 0

            setActiveState((prev) => {
                if (turningOn) return { ...prev, [index]: "playing" }
                const next = { ...prev }
                delete next[index]
                return next
            })
        },
        [gridPads, activeState, primeToggleTrack]
    )

    // Max Volume is otherwise only applied at the moment a pad is toggled
    // on. Without this, editing it in Framer while a pad is already
    // playing has no audible effect until you toggle it off and back on —
    // which reads as "the setting doesn't work." This keeps every
    // currently-on pad's gain live-synced to its own Max Volume value.
    React.useEffect(() => {
        gridPads.forEach((pad, index) => {
            if (activeState[index] !== "playing") return
            const gain = toggleGainsRef.current.get(index)
            if (!gain) return
            const maxVolume = maxVolumeToGain(pad.maxVolume ?? 100)
            gain.gain.setTargetAtTime(maxVolume, gain.context.currentTime, 0.05)
        })
    }, [gridPads, activeState])

    const stopAll = React.useCallback(() => {
        // tap-mode one-shots: stop outright
        Array.from(sourcesRef.current.keys()).forEach(stopPad)
        // held-on tracks: mute rather than stop, so they stay perfectly in
        // sync underneath and are ready to unmute instantly
        toggleGainsRef.current.forEach((gain) => {
            gain.gain.value = 0
        })
        setActiveState((prev) => {
            const next = { ...prev }
            toggleGainsRef.current.forEach((_, index) => {
                delete next[index]
            })
            return next
        })
    }, [stopPad])

    React.useEffect(() => {
        const echoDelay = echoDelayRef.current
        if (!echoDelay) return
        echoDelay.delayTime.setTargetAtTime(
            Math.max(0.05, 60 / bpm / 2),
            echoDelay.context.currentTime,
            0.05
        )
    }, [bpm])

    // sets a knob's value (-50..50) and scales its effect's wet level by
    // how far from center it's been turned, in either direction
    const setFxValue = React.useCallback((key: FxKey, rawValue: number) => {
        const clamped = Math.max(-50, Math.min(50, Math.round(rawValue)))
        setFxValues((prev) => {
            if (prev[key] === clamped) return prev
            return { ...prev, [key]: clamped }
        })
        const wetGain = fxWetGainsRef.current[key]
        if (wetGain) {
            // sub-linear (concave) curve: a moderate turn already sounds
            // meaningfully present instead of only becoming audible near
            // the top of the knob's travel — full turn still lands on
            // exactly FX_WET_LEVELS[key], unchanged
            const intensity = Math.pow(Math.abs(clamped) / 50, 0.6)
            wetGain.gain.setTargetAtTime(
                intensity * FX_WET_LEVELS[key],
                wetGain.context.currentTime,
                0.03
            )
        }
    }, [])

    const startKnobDrag = React.useCallback(
        (key: FxKey) => (e: React.PointerEvent<HTMLButtonElement>) => {
            getContext()
            try {
                e.currentTarget.setPointerCapture(e.pointerId)
            } catch (err) {
                // no active pointer session to capture; safe to ignore
            }
            knobDragRef.current = {
                key,
                startY: e.clientY,
                startValue: fxValues[key],
            }
            setLastTouchedParam(key)
            setDraggingFxKey(key)
        },
        [getContext, fxValues]
    )

    const dragKnob = React.useCallback(
        (e: React.PointerEvent<HTMLButtonElement>) => {
            const drag = knobDragRef.current
            if (!drag || e.buttons !== 1) return
            const deltaY = drag.startY - e.clientY
            setFxValue(drag.key, drag.startValue + deltaY * 0.5)
        },
        [setFxValue]
    )

    const endKnobDrag = React.useCallback(() => {
        knobDragRef.current = null
        setDraggingFxKey(null)
    }, [])

    const setCutoffKnobValue = React.useCallback((rawValue: number) => {
        const clamped = Math.max(-50, Math.min(50, Math.round(rawValue)))
        setCutoffValue((prev) => (prev === clamped ? prev : clamped))
        const filter = filterNodeRef.current
        if (filter) applyFilterValue(filter, clamped)
    }, [])

    const startCutoffDrag = React.useCallback(
        (e: React.PointerEvent<HTMLButtonElement>) => {
            getContext()
            try {
                e.currentTarget.setPointerCapture(e.pointerId)
            } catch (err) {
                // no active pointer session to capture; safe to ignore
            }
            cutoffDragRef.current = {
                startY: e.clientY,
                startValue: cutoffValue,
            }
            setLastTouchedParam("cutoff")
            setIsDraggingCutoff(true)
        },
        [getContext, cutoffValue]
    )

    const dragCutoff = React.useCallback(
        (e: React.PointerEvent<HTMLButtonElement>) => {
            const drag = cutoffDragRef.current
            if (!drag || e.buttons !== 1) return
            const deltaY = drag.startY - e.clientY
            setCutoffKnobValue(drag.startValue + deltaY * 0.5)
        },
        [setCutoffKnobValue]
    )

    const endCutoffDrag = React.useCallback(() => {
        cutoffDragRef.current = null
        setIsDraggingCutoff(false)
    }, [])

    React.useEffect(() => {
        return () => {
            sourcesRef.current.forEach((src) => {
                try {
                    src.stop()
                } catch (e) {
                    // already stopped
                }
            })
            toggleSourcesRef.current.forEach((src) => {
                try {
                    src.stop()
                } catch (e) {
                    // already stopped
                }
            })
            timeoutsRef.current.forEach((t) => clearTimeout(t))
            if (ctxRef.current) ctxRef.current.close()
        }
    }, [])

    React.useEffect(() => {
        const canvas = visCanvasRef.current
        const canvasCtx = canvas?.getContext("2d")
        if (!canvas || !canvasCtx) return

        // draw at native (DPR-scaled) resolution matching the canvas's
        // actual CSS size 1:1, so bars render crisp instead of being
        // stretched up from a tiny low-res buffer
        const dpr = window.devicePixelRatio || 1
        canvas.width = VIS_WIDTH * dpr
        canvas.height = VIS_HEIGHT * dpr
        canvasCtx.scale(dpr, dpr)

        const barWidth = 2
        const gap = 1
        const numBars = Math.max(
            1,
            Math.floor((VIS_WIDTH + gap) / (barWidth + gap))
        )
        const drawnWidth = numBars * (barWidth + gap) - gap
        const offsetX = (VIS_WIDTH - drawnWidth) / 2

        const freqData = new Uint8Array(32)

        const draw = () => {
            rafRef.current = requestAnimationFrame(draw)
            const analyser = analyserRef.current
            if (analyser) {
                analyser.getByteFrequencyData(freqData)
            } else {
                freqData.fill(0)
            }
            canvasCtx.clearRect(0, 0, VIS_WIDTH, VIS_HEIGHT)
            for (let i = 0; i < numBars; i++) {
                const x = offsetX + i * (barWidth + gap)
                const bin = Math.floor((i / numBars) * freqData.length)
                const amp = freqData[bin] / 255
                const litHeight = Math.round(amp * VIS_HEIGHT)

                canvasCtx.fillStyle = "rgba(255,255,255,0.05)"
                canvasCtx.fillRect(x, 0, barWidth, VIS_HEIGHT)

                if (litHeight > 0) {
                    canvasCtx.fillStyle = `hsla(${hue}, 90%, ${55 + amp * 20}%, ${0.5 + amp * 0.5})`
                    canvasCtx.fillRect(
                        x,
                        VIS_HEIGHT - litHeight,
                        barWidth,
                        litHeight
                    )
                }
            }
        }
        draw()
        return () => {
            if (rafRef.current !== null) cancelAnimationFrame(rafRef.current)
        }
    }, [hue])

    const activeCount = Object.keys(activeState).length
    const glowOpacity = Math.min(0.85, 0.4 + activeCount * 0.05)

    const readoutLabel =
        lastTouchedParam === null
            ? "FX"
            : lastTouchedParam === "cutoff"
              ? "Cutoff"
              : FX_LABELS[lastTouchedParam]
    const readoutRawValue =
        lastTouchedParam === null
            ? null
            : lastTouchedParam === "cutoff"
              ? cutoffValue
              : fxValues[lastTouchedParam]
    const readoutValueText =
        readoutRawValue === null
            ? "--"
            : readoutRawValue > 0
              ? `+${readoutRawValue}`
              : `${readoutRawValue}`

    const padButtons = gridPads.map((pad, i) => {
        const state = activeState[i]
        const hasAudio = Boolean(pad.audio)
        const isTap = pad.mode === "tap"
        const isActive = state === "playing" || state === "queued"
        return (
            <button
                key={i}
                className="beatpad-pad"
                data-active={isActive}
                disabled={!hasAudio}
                style={padStyle(
                    state,
                    hasAudio,
                    hue,
                    padDefaultColor,
                    isMobile
                )}
                onClick={
                    isTap ? () => triggerTapPad(i, pad) : () => togglePad(i)
                }
            >
                {padTextureSrc && (
                    <span
                        style={padTextureOverlayStyle(
                            Boolean(state),
                            padTextureOpacity,
                            4,
                            padTextureSrc
                        )}
                    />
                )}
                <span style={padNumberStyle(Boolean(state))}>
                    {String(i + 1).padStart(2, "0")}
                </span>
                {isTap ? (
                    <span style={padDotStyle(Boolean(state), hue)} />
                ) : (
                    <span style={padIconStyle(Boolean(state))}>
                        {padIcon(state)}
                    </span>
                )}
                <span style={padLabelStyle(Boolean(state))}>
                    {pad.label || (hasAudio ? `Pad ${i + 1}` : "Empty")}
                </span>
                <span style={padBevelOverlayStyle(4)} />
            </button>
        )
    })

    // single-instrument row: stripped-down pads (no number, no play/hold
    // icon — just a label) that always tap-trigger a one-shot, and fill
    // solid with the backlight hue while playing instead of the main
    // pads' glow-and-icon treatment. Shares the exact same tap-trigger
    // machinery as the main grid via an offset index, so double-tap
    // cancellation, Max Volume, and the global STOP button all just work.
    // Pads without audio are skipped entirely rather than rendered dim —
    // the original slot index (not the filtered position) still backs the
    // offset used for activeState/sourcesRef/etc, so nothing shifts if a
    // pad earlier in the list is filled in later.
    const configuredInstrumentPads = instrumentGridPads
        .map((pad, i) => ({ pad, i }))
        .filter(({ pad }) => Boolean(pad.audio))
    const instrumentPadButtons = configuredInstrumentPads.map(({ pad, i }) => {
        const index = INSTRUMENT_INDEX_OFFSET + i
        const state = activeState[index]
        const isActive = state === "playing" || state === "queued"
        return (
            <button
                key={index}
                className="beatpad-pad"
                data-active={isActive}
                style={instrumentPadStyle(
                    state,
                    true,
                    hue,
                    padDefaultColor,
                    isMobile
                )}
                onClick={() => triggerTapPad(index, pad)}
            >
                {padTextureSrc && (
                    <span
                        style={padTextureOverlayStyle(
                            Boolean(state),
                            padTextureOpacity,
                            4,
                            padTextureSrc
                        )}
                    />
                )}
                <span style={instrumentPadLabelStyle(Boolean(state))}>
                    {pad.label || `Inst ${i + 1}`}
                </span>
                <span style={padBevelOverlayStyle(4)} />
            </button>
        )
    })

    const knobSize = useCompactHeader ? MOBILE_KNOB_SIZE : FX_KNOB_SIZE

    const woodToggleEl = (
        <div className="beatpad-knob-wrap" style={{ display: "flex" }}>
            <span className="beatpad-knob-tooltip">Wood Faceplate</span>
            <button
                style={powerKnobStyle(woodFaceplate)}
                onClick={() => setWoodFaceplate((prev) => !prev)}
                aria-label="Toggle walnut wood faceplate"
            />
        </div>
    )

    const stopButtonEl = (
        <div style={stopHitAreaStyle(isMobile)}>
            <button style={squareButtonStyle} onClick={stopAll}>
                STOP
            </button>
        </div>
    )

    const bpmChipEl = (
        <div style={infoChipStyle}>
            <span
                style={{
                    width: 6,
                    height: 6,
                    borderRadius: "50%",
                    background: KNOB_ACCENT,
                    boxShadow: `0 0 5px ${KNOB_ACCENT}`,
                    flexShrink: 0,
                    animation: `beatpad-bpm-blink ${60 / Math.max(1, bpm)}s linear infinite`,
                }}
            />
            <span style={infoChipValueStyle}>{bpm}</span>
            <span style={infoChipLabelStyle}>BPM</span>
        </div>
    )

    const logoJustify =
        logoAlign === "left"
            ? "flex-start"
            : logoAlign === "right"
              ? "flex-end"
              : "center"

    // wrapped in a flex:1 spacer that claims the whole gap between the
    // left cluster and the fx knobs, so logoAlign positions the text
    // within that gap (flush left/right or centered) instead of just
    // wherever space-between happens to land a middle flex item
    // hidden on the phone breakpoint specifically — there's no spare room
    // for it once the header stacks knobs-on-top there; still shows on
    // tablet (which keeps a bounded card with more breathing room) and
    // desktop
    const logoEl =
        showLogo && !isMobile ? (
            <div
                style={{
                    flex: 1,
                    display: "flex",
                    justifyContent: logoJustify,
                    minWidth: 0,
                }}
            >
                <span
                    style={{
                        display: "flex",
                        alignItems: "baseline",
                        gap: "0.3em",
                        fontFamily:
                            "'Funnel Sans', 'Helvetica Neue', sans-serif",
                        letterSpacing: logoLetterSpacing,
                        color: logoColor,
                        whiteSpace: "nowrap",
                    }}
                >
                    {logoWords.map((word, i) => (
                        <span
                            key={i}
                            style={{
                                fontSize:
                                    word.fontSize > 0
                                        ? word.fontSize
                                        : logoFontSize,
                                fontWeight:
                                    word.fontWeight > 0
                                        ? word.fontWeight
                                        : logoFontWeight,
                            }}
                        >
                            {word.text}
                        </span>
                    ))}
                </span>
            </div>
        ) : null

    const fxKnobElements = [
        ...(["echo", "flanger", "phaser", "reverb"] as FxKey[]).map((key) => (
            <div key={key} className="beatpad-knob-wrap" style={knobWrapStyle}>
                <button
                    style={fxKnobButtonStyle(knobSize)}
                    onPointerDown={startKnobDrag(key)}
                    onPointerMove={dragKnob}
                    onPointerUp={endKnobDrag}
                    onPointerCancel={endKnobDrag}
                    aria-label={FX_LABELS[key]}
                >
                    {fxKnobSvg(fxValues[key], knobSize)}
                </button>
                <span className="beatpad-fx-knob-label">{FX_LABELS[key]}</span>
            </div>
        )),
        <div key="cutoff" className="beatpad-knob-wrap" style={knobWrapStyle}>
            <div style={knobButtonSlotStyle}>
                {cutoffDotRingSvg(knobSize)}
                <button
                    style={fxKnobButtonStyle(knobSize)}
                    onPointerDown={startCutoffDrag}
                    onPointerMove={dragCutoff}
                    onPointerUp={endCutoffDrag}
                    onPointerCancel={endCutoffDrag}
                    aria-label="Cutoff"
                >
                    {cutoffKnobSvg(cutoffValue, knobSize)}
                </button>
            </div>
            <span className="beatpad-fx-knob-label">Cutoff</span>
        </div>,
    ]

    const fxReadoutPanelEl = (
        <div style={fxReadoutPanelStyle}>
            <div style={fxReadoutLabelGroupStyle}>
                <img
                    src={
                        isDraggingCutoff
                            ? FX_CUTOFF_GIF
                            : draggingFxKey
                              ? FX_KNOB_GIFS[draggingFxKey]
                              : FX_LOADER_GIF
                    }
                    alt=""
                    style={fxLoaderGifStyle}
                />
                <span style={fxReadoutLabelStyle}>{readoutLabel}</span>
            </div>
            <span
                style={fxReadoutValueStyle(
                    lastTouchedParam === "cutoff"
                        ? KNOB_ACCENT
                        : KNOB_ACCENT_NEUTRAL
                )}
            >
                {readoutValueText}
            </span>
        </div>
    )

    return (
        <div
            ref={outerRef}
            className="beatpad-sampler-root"
            style={{
                ...outerStyle,
                background: backgroundColor,
                ...(backgroundImageSrc
                    ? {
                          backgroundImage: `url("${backgroundImageSrc}")`,
                          backgroundSize: "cover",
                          backgroundPosition: "center",
                          backgroundAttachment: "fixed",
                          backgroundRepeat: "no-repeat",
                      }
                    : null),
                ...style,
                // on mobile the widget grows with its content instead of
                // being pinned to a fixed viewport height — if the pad
                // grid doesn't fit, the page just gets taller rather than
                // scrolling inside a clipped box. Has to come after
                // ...style, not before it — Framer passes the frame's own
                // fixed height through that prop, which was silently
                // overriding this and pinning the height anyway.
                ...(isMobile ? { height: "auto" } : null),
            }}
        >
            <style>{`
                @import url('https://fonts.googleapis.com/css2?family=Funnel+Sans:wght@400;500;600;700;800&display=swap');
                .beatpad-sampler-root button,
                .beatpad-sampler-root .beatpad-hue-track {
                    -webkit-tap-highlight-color: transparent;
                    -webkit-user-select: none;
                    user-select: none;
                }
                @keyframes beatpad-pulse {
                    0%, 100% { opacity: 0.6; transform: scale(0.98); }
                    50% { opacity: 1; transform: scale(1.02); }
                }
                @keyframes beatpad-bpm-blink {
                    0%, 100% { opacity: 0.25; transform: scale(0.85); }
                    8% { opacity: 1; transform: scale(1); }
                    30% { opacity: 0.25; transform: scale(0.85); }
                }
                .beatpad-knob-wrap {
                    position: relative;
                }
                .beatpad-knob-tooltip {
                    position: absolute;
                    bottom: calc(100% + 7px);
                    left: 50%;
                    transform: translateX(-50%);
                    background: #000;
                    color: #fff;
                    font-size: 8px;
                    font-weight: 700;
                    letter-spacing: 0.4px;
                    text-transform: uppercase;
                    padding: 3px 6px;
                    border-radius: 4px;
                    white-space: nowrap;
                    opacity: 0;
                    pointer-events: none;
                    transition: opacity 0.12s ease;
                    z-index: 1;
                }
                .beatpad-knob-wrap:hover .beatpad-knob-tooltip {
                    opacity: 1;
                }
                .beatpad-fx-knob-label {
                    font-size: 8px;
                    font-weight: 600;
                    letter-spacing: 0.3px;
                    color: rgba(255,255,255,0.5);
                    white-space: nowrap;
                }
                .beatpad-pad:not(:disabled):not([data-active="true"]):hover {
                    filter: brightness(1.18);
                }
            `}</style>

            {backgroundImageSrc && <div style={backgroundScrimStyle} />}

            {/* topo-pattern (or any) texture layer — sits above the
                background image but below the groove box body. Recolored
                via a CSS mask instead of an <img>, since a mask lets an
                arbitrary uploaded image (any source color/transparency)
                be tinted to any solid color the user picks, rather than
                only being able to hue-shift or darken its original art.
                Always sized to fully cover the canvas as one instance
                (never tiled — tiling created visible seams/banding at
                the repeat boundaries); textureScale zooms in past that
                cover-fit baseline instead of changing a tile size, so
                it's guaranteed to still fully cover at every setting.
                The wrapper clips the zoomed-in overflow so scaling up
                can't bleed past the canvas edges. */}
            {textureImageSrc && (
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        overflow: "hidden",
                    }}
                >
                    <div
                        style={{
                            position: "absolute",
                            inset: 0,
                            opacity: textureOpacity / 100,
                            backgroundColor: textureColor,
                            transform: `scale(${textureScale / 10})`,
                            WebkitMaskImage: `url("${textureImageSrc}")`,
                            maskImage: `url("${textureImageSrc}")`,
                            WebkitMaskSize: "cover",
                            maskSize: "cover",
                            WebkitMaskPosition: "center",
                            maskPosition: "center",
                            WebkitMaskRepeat: "no-repeat",
                            maskRepeat: "no-repeat",
                            pointerEvents: "none",
                        }}
                    />
                </div>
            )}

            {/* ambient backlight, driven by the color line below the pads */}
            <div
                style={{
                    ...glowLayerStyle,
                    width: glowSize * 8,
                    height: glowSize * 8,
                    opacity: glowOpacity,
                    filter: `blur(${glowSize * 0.75}px)`,
                    background: `radial-gradient(circle, hsl(${hue}, 90%, 55%) 0%, hsl(${hue}, 85%, 40%) 45%, transparent 75%)`,
                }}
            />

            <div
                style={{
                    ...bodyStyle,
                    ...bodyDimsStyle(isHorizontal, isMobile, isTablet),
                    ...(woodFaceplate
                        ? {
                              backgroundImage: `url("${faceplateTextureSrc}")`,
                              backgroundSize: "cover",
                              backgroundPosition: "center",
                              backgroundRepeat: "no-repeat",
                              boxShadow: woodBezelBoxShadow,
                          }
                        : defaultFaceplateTextureSrc
                          ? {
                                backgroundImage: `url("${defaultFaceplateTextureSrc}")`,
                                backgroundSize: "cover",
                                backgroundPosition: "center",
                                backgroundRepeat: "no-repeat",
                            }
                          : { background: faceplateGradient(faceplateColor) }),
                }}
            >
                <div style={noiseOverlayStyle} />
                <div
                    style={
                        useCompactHeader ? mobileHeaderRowStyle : headerRowStyle
                    }
                >
                    {useCompactHeader ? (
                        <>
                            <div style={mobileKnobRowStyle}>
                                {fxKnobElements}
                            </div>
                            <div style={mobileControlRowStyle}>
                                <div style={leftClusterStyle}>
                                    {woodToggleEl}
                                    {stopButtonEl}
                                    {bpmChipEl}
                                </div>
                                {logoEl}
                                {fxReadoutPanelEl}
                            </div>
                        </>
                    ) : (
                        <>
                            <div style={leftClusterStyle}>
                                {woodToggleEl}
                                {stopButtonEl}
                                {bpmChipEl}
                            </div>
                            {logoEl}
                            <div style={fxKnobRowStyle}>
                                {fxKnobElements}
                                {fxReadoutPanelEl}
                            </div>
                        </>
                    )}
                </div>

                <div
                    style={{
                        ...screenStyle,
                        ...screenGlassStyle(
                            hue,
                            backgroundImageSrc,
                            glassOpacity
                        ),
                    }}
                >
                    <div style={screenSheenStyle} />
                    <div style={screenTextRowStyle}>
                        <div style={screenTextColStyle}>
                            <span style={screenTitleStyle}>{screenLabel}</span>
                            <span style={screenSubStyle}>
                                {barsPerLoop} BAR{barsPerLoop > 1 ? "S" : ""} /
                                LOOP
                                {activeCount > 0
                                    ? ` · ${activeCount} ACTIVE`
                                    : ""}
                            </span>
                        </div>
                        <canvas
                            ref={visCanvasRef}
                            width={VIS_WIDTH}
                            height={VIS_HEIGHT}
                            style={visualizerCanvasStyle}
                        />
                    </div>
                </div>

                {isMobile ? (
                    <div ref={gridWrapRef} style={mobileGridWrapStyle}>
                        <div style={mobileGridStyle(mobileSquareSize)}>
                            {padButtons}
                        </div>
                    </div>
                ) : (
                    <div
                        style={{
                            ...gridStyle,
                            gridTemplateColumns: isHorizontal
                                ? "repeat(8, 1fr)"
                                : "repeat(4, 1fr)",
                        }}
                    >
                        {padButtons}
                    </div>
                )}

                {configuredInstrumentPads.length > 0 &&
                    (isMobile ? (
                        <div style={instrumentMobileGridWrapStyle}>
                            <div
                                style={instrumentMobileGridStyle(
                                    mobileSquareSize
                                )}
                            >
                                {instrumentPadButtons}
                            </div>
                        </div>
                    ) : (
                        <div
                            style={instrumentRowStyle(
                                Math.min(
                                    configuredInstrumentPads.length,
                                    isTablet ? 8 : 16
                                )
                            )}
                        >
                            {instrumentPadButtons}
                        </div>
                    ))}

                {showHueSlider && (
                    <div style={sliderRowStyle}>
                        <span style={sliderLabelStyle}>Backlight</span>
                        <div
                            ref={hueTrackRef}
                            className="beatpad-hue-track"
                            style={hueTrackWrapperStyle}
                            onPointerDown={handleHuePointerDown}
                            onPointerMove={handleHuePointerMove}
                        >
                            <div style={hueBaseLineStyle} />
                            <div
                                style={{
                                    ...hueFillStyle,
                                    width: `${(hue / 360) * 100}%`,
                                    background: `hsl(${hue}, 75%, 55%)`,
                                }}
                            />
                            <div
                                style={{
                                    ...hueThumbStyle,
                                    left: `${(hue / 360) * 100}%`,
                                    background: `hsl(${hue}, 85%, 62%)`,
                                    boxShadow: `0 0 8px hsla(${hue}, 85%, 60%, 0.8)`,
                                }}
                            />
                        </div>
                    </div>
                )}
            </div>
        </div>
    )
}

