// plugin-style knob: dark flat face, a dim 270° track (gap at the bottom),
// and an orange arc that fills from center toward the current value —
// modeled on the reference UI. Value is a continuous bipolar -50..50,
// adjusted by vertical click-drag like a real knob, with 0 at 12 o'clock.
const KNOB_MIN_ANGLE = -135
const KNOB_MAX_ANGLE = 135
const KNOB_ACCENT = "#ea7a2b"
const KNOB_ACCENT_NEUTRAL = "#b8b8bc"
const KNOB_BASE_COLOR = "#202023"

function polarToCartesian(
    cx: number,
    cy: number,
    r: number,
    angleDeg: number
): { x: number; y: number } {
    const rad = ((angleDeg - 90) * Math.PI) / 180
    return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) }
}

function describeArc(
    cx: number,
    cy: number,
    r: number,
    startAngle: number,
    endAngle: number
): string {
    if (endAngle <= startAngle) return ""
    const start = polarToCartesian(cx, cy, r, startAngle)
    const end = polarToCartesian(cx, cy, r, endAngle)
    const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1"
    return `M ${start.x} ${start.y} A ${r} ${r} 0 ${largeArcFlag} 1 ${end.x} ${end.y}`
}

function fxKnobSvg(
    value: number,
    size: number = FX_KNOB_SIZE
): React.ReactNode {
    const cx = size / 2
    const cy = size / 2
    const r = cx - 4
    const valueAngle = (value / 50) * KNOB_MAX_ANGLE
    const tickStart = polarToCartesian(cx, cy, r - 8, valueAngle)
    const tickEnd = polarToCartesian(cx, cy, r - 1, valueAngle)
    const centerMark = polarToCartesian(cx, cy, r, 0)
    const hasArc = Math.abs(value) >= 1
    const arcPath =
        value >= 0
            ? describeArc(cx, cy, r, 0, Math.max(valueAngle, 0.01))
            : describeArc(cx, cy, r, valueAngle, 0)

    return (
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
            <circle cx={cx} cy={cy} r={cx} fill={KNOB_BASE_COLOR} />
            <circle cx={cx} cy={cy} r={r - 2} fill="#101012" />
            <path
                d={describeArc(cx, cy, r, KNOB_MIN_ANGLE, KNOB_MAX_ANGLE)}
                fill="none"
                stroke="rgba(255,255,255,0.14)"
                strokeWidth={2.6}
                strokeLinecap="round"
            />
            {hasArc && (
                <path
                    d={arcPath}
                    fill="none"
                    stroke={KNOB_ACCENT_NEUTRAL}
                    strokeWidth={2.6}
                    strokeLinecap="round"
                />
            )}
            <circle
                cx={centerMark.x}
                cy={centerMark.y}
                r={1.4}
                fill="rgba(255,255,255,0.35)"
            />
            <line
                x1={tickStart.x}
                y1={tickStart.y}
                x2={tickEnd.x}
                y2={tickEnd.y}
                stroke="#ffffff"
                strokeWidth={2}
                strokeLinecap="round"
            />
        </svg>
    )
}

