// "Content"-style knob: no dim track, a thick glowing arc that always
// fills from the fixed 7-o'clock minimum up to the current value, and a
// dark flat face — matches the reference image exactly, distinct from the
// thinner center-filling arcs used on the 4 FX knobs above.
function cutoffKnobSvg(
    value: number,
    size: number = FX_KNOB_SIZE
): React.ReactNode {
    const cx = size / 2
    const cy = size / 2
    const r = cx - 5
    const valueAngle =
        KNOB_MIN_ANGLE +
        ((value + 50) / 100) * (KNOB_MAX_ANGLE - KNOB_MIN_ANGLE)
    const tickStart = polarToCartesian(cx, cy, r - 9, valueAngle)
    const tickEnd = polarToCartesian(cx, cy, r + 1, valueAngle)
    const hasArc = valueAngle > KNOB_MIN_ANGLE + 0.5

    return (
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
            <circle cx={cx} cy={cy} r={cx} fill={KNOB_BASE_COLOR} />
            <circle cx={cx} cy={cy} r={r - 2} fill="#101012" />
            {hasArc && (
                <path
                    d={describeArc(cx, cy, r, KNOB_MIN_ANGLE, valueAngle)}
                    fill="none"
                    stroke={KNOB_ACCENT}
                    strokeWidth={4}
                    strokeLinecap="round"
                />
            )}
            <line
                x1={tickStart.x}
                y1={tickStart.y}
                x2={tickEnd.x}
                y2={tickEnd.y}
                stroke="#ffffff"
                strokeWidth={2}
                strokeLinecap="round"
            />
        </svg>
    )
}

// decorative dotted ring around the cutoff knob only — very small dots
// tracing the circle, with a gap left open at the bottom (clock-face
// analogy: nothing drawn between 4 o'clock and 8 o'clock, i.e. the
// 120°-240° range in this component's clock-style angle system, where
// 0° = 12 o'clock and angles increase clockwise).
function cutoffDotRingSvg(size: number): React.ReactNode {
    const ringSize = size + 20
    const cx = ringSize / 2
    const cy = ringSize / 2
    const orbitRadius = size / 2 + 6
    const dotRadius = 1
    const stepDeg = 15
    const dots: React.ReactNode[] = []
    for (let angle = -120; angle <= 120; angle += stepDeg) {
        const { x, y } = polarToCartesian(cx, cy, orbitRadius, angle)
        dots.push(
            <circle
                key={angle}
                cx={x}
                cy={y}
                r={dotRadius}
                fill="rgba(255,255,255,0.4)"
            />
        )
    }

    return (
        <svg
            width={ringSize}
            height={ringSize}
            viewBox={`0 0 ${ringSize} ${ringSize}`}
            style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                transform: "translate(-50%, calc(-50% + 2px))",
                pointerEvents: "none",
            }}
        >
            {dots}
        </svg>
    )
}

