function mobileGridStyle(squareSize: number | null): React.CSSProperties {
    if (squareSize === null) {
        return {
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gridTemplateRows: "repeat(4, 1fr)",
            gap: GRID_GAP,
            width: "100%",
            height: "100%",
        }
    }
    return {
        display: "grid",
        gridTemplateColumns: `repeat(4, ${squareSize}px)`,
        gridTemplateRows: `repeat(4, ${squareSize}px)`,
        gap: GRID_GAP,
    }
}

// desktop: all 16 fill one row, edge to edge, matching the main grid's
// width above it. Tablet caps at 8 columns (wraps to a 2nd row of 8).
// Fixed 1fr columns from a constant column count (not the pad count)
// also guarantee the row can never overflow its container — except plain
// `1fr` is shorthand for `minmax(auto, 1fr)`, and that `auto` minimum
// still lets an aspect-ratio item's content-driven size win over the
// fair 1fr share regardless of the item's own min-width/min-height.
// minmax(0, 1fr) overrides that at the track level, which is the only
// place that actually stopped the row from blowing past its container.
function instrumentRowStyle(columns: number): React.CSSProperties {
    return {
        display: "grid",
        gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
        gap: GRID_GAP,
        // minmax(0, 1fr) handles the real overflow case, but distributing
        // a fractional pixel width across many tracks still leaves a
        // stray sub-pixel remainder in some browsers — clip it so
        // "never overflows" is a hard guarantee, not just very close
        overflow: "hidden",
    }
}

// mobile: a second 4x4 grid under the main one, using the exact same
// measured mobileSquareSize (not a fraction of it) so its pads are the
// same size and its left/right edges line up flush with the main grid
// above, instead of sitting as a smaller centered block with dead space
// on either side
const instrumentMobileGridWrapStyle: React.CSSProperties = {
    marginTop: GRID_GAP,
    display: "flex",
    alignItems: "flex-start",
    justifyContent: "center",
}

function instrumentMobileGridStyle(
    squareSize: number | null
): React.CSSProperties {
    if (squareSize === null) {
        return {
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gridTemplateRows: "repeat(4, 1fr)",
            gap: GRID_GAP,
            width: "100%",
            height: "100%",
        }
    }
    return {
        display: "grid",
        gridTemplateColumns: `repeat(4, ${squareSize}px)`,
        gridAutoRows: `${squareSize}px`,
        gap: GRID_GAP,
    }
}

// optional global texture layered over every pad's own gradient (both the
// main grid and the instrument row) — sits above that gradient as its own
// element so it gets an independent opacity, rather than dimming the
// gradient underneath it. Faded out on an active/lit pad, since that
// state already has its own distinct treatment (glow border or solid
// hue fill) that the texture would just muddy.
function padTextureOverlayStyle(
    isActive: boolean,
    opacity: number,
    borderRadius: number,
    src: string
): React.CSSProperties {
    return {
        position: "absolute",
        inset: 0,
        borderRadius,
        backgroundImage: `url("${src}")`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        backgroundRepeat: "no-repeat",
        opacity: isActive ? 0 : opacity / 100,
        pointerEvents: "none",
        transition: "opacity 0.15s ease",
    }
}

// rim-light bevel as its own top layer, above the pad texture image
// rather than baked into the button's own (lower) box-shadow — so a
// configured texture never hides it. Matches the component's global
// light source (up and to the left): a bright highlight hugging the
// top-left inner edge, fading to a soft shadow on the opposite
// bottom-right edge.
function padBevelOverlayStyle(borderRadius: number): React.CSSProperties {
    return {
        position: "absolute",
        inset: 0,
        borderRadius,
        boxShadow:
            "inset 3px 3px 4px rgba(255,255,255,0.16), inset -3px -3px 5px rgba(0,0,0,0.35)",
        pointerEvents: "none",
    }
}

function padStyle(
    state: "queued" | "playing" | undefined,
    hasAudio: boolean,
    hue: number,
    defaultColor: string,
    isMobile: boolean
): React.CSSProperties {
    const isPlaying = state === "playing"
    const isQueued = state === "queued"
    return {
        position: "relative",
        display: "flex",
        flexDirection: "column",
        justifyContent: "space-between",
        alignItems: "flex-start",
        padding: 8,
        borderRadius: 4,
        boxSizing: "border-box",
        cursor: hasAudio ? "pointer" : "default",
        outline: "none",
        textAlign: "left",
        fontFamily: "inherit",
        // a thick, near-black stroke rather than a thin hairline — reads
        // as a physical gap/recess around the pad instead of a flat
        // outline, matching a real hardware pad's cutout groove. When
        // playing it's only lightly tinted (30%) by the backlight color
        // rather than fully recolored — flooded by the glow rather than
        // switching hue outright.
        border: isPlaying
            ? `4px solid color-mix(in srgb, hsl(${hue}, 65%, 58%) 30%, #080808)`
            : "4px solid #080808",
        // soft radial glow rather than a directional gradient — bright,
        // slightly-above-center core fading out to a darker edge, like a
        // backlit silicone pad rather than a flat panel catching light.
        // Idle pads use the user-set default color (auto-lightened/
        // darkened into a gradient via color-mix); only playing pads
        // switch to the hue-driven backlight color.
        background: isPlaying
            ? `radial-gradient(circle at 50% 42%, hsl(${hue}, 88%, 76%) 0%, hsl(${hue}, 82%, 56%) 45%, hsl(${hue}, 72%, 36%) 100%)`
            : hasAudio
              ? `radial-gradient(circle at 50% 42%, color-mix(in srgb, ${defaultColor} 100%, white 22%) 0%, ${defaultColor} 55%, color-mix(in srgb, ${defaultColor} 100%, black 35%) 100%)`
              : "radial-gradient(circle at 50% 42%, #26262a 0%, #1c1c1f 60%, #161618 100%)",
        // the rim-light bevel used to live here as an inset shadow, but
        // that paints underneath the pad texture image (a later sibling)
        // — moved out to padBevelOverlayStyle, a separate top layer, so it
        // stays visible over the texture. What's left is the glow (a
        // tight near-edge layer so it visibly washes out over the fixed
        // dark stroke, plus a softer wider halo beyond it) and a
        // bottom-right ambient shadow, biased away from the global
        // upper-left light source along with everything else
        boxShadow: isPlaying
            ? `0 0 6px hsla(${hue}, 90%, 65%, 0.9), 0 0 22px hsla(${hue}, 85%, 60%, 0.5), inset -2px -3px 6px rgba(0,0,0,0.3)`
            : hasAudio
              ? `0 0 12px color-mix(in srgb, ${defaultColor} 55%, transparent), inset -2px -3px 6px rgba(0,0,0,0.35)`
              : "inset -2px -3px 6px rgba(0,0,0,0.35)",
        opacity: hasAudio ? 1 : 0.4,
        animation: isQueued
            ? "beatpad-pulse 0.5s ease-in-out infinite"
            : "none",
        transition:
            "background 0.15s ease, box-shadow 0.15s ease, border 0.15s ease, filter 0.15s ease",
        ...(isMobile ? { width: "100%", height: "100%" } : { minHeight: 58 }),
    }
}

// dark near-black rather than white once active — the backlit fill is
// bright enough there that white text loses contrast against it; a dark
// tone reads clearly across the gradient's range instead. Matches the
// same rgba(0,0,0,0.75) already used for instrument pad labels.
function padNumberStyle(isActive: boolean): React.CSSProperties {
    return {
        position: "relative",
        fontSize: 9,
        fontWeight: 700,
        letterSpacing: 0.5,
        color: isActive ? "rgba(0,0,0,0.75)" : "rgba(255,255,255,0.32)",
    }
}

function padIconStyle(isActive: boolean): React.CSSProperties {
    return {
        position: "relative",
        alignSelf: "center",
        color: isActive ? "rgba(0,0,0,0.75)" : "rgba(255,255,255,0.85)",
    }
}

function padIcon(state: "queued" | "playing" | undefined): React.ReactNode {
    // rendered as inline SVG rather than a unicode glyph (▶ / ❚❚ / …) so the
    // icon can't get swapped out for a platform emoji/symbol font on mobile
    if (state === "playing") {
        return (
            <svg width="13" height="13" viewBox="0 0 16 16" fill="currentColor">
                <rect x="3" y="2" width="3.5" height="12" rx="0.5" />
                <rect x="9.5" y="2" width="3.5" height="12" rx="0.5" />
            </svg>
        )
    }
    if (state === "queued") {
        return (
            <svg width="13" height="13" viewBox="0 0 16 16" fill="currentColor">
                <circle cx="3" cy="8" r="1.6" />
                <circle cx="8" cy="8" r="1.6" />
                <circle cx="13" cy="8" r="1.6" />
            </svg>
        )
    }
    return (
        <svg width="13" height="13" viewBox="0 0 16 16" fill="currentColor">
            <path d="M4 2.2v11.6c0 .6.66 1 1.2.66l9-5.8c.5-.32.5-1.06 0-1.38l-9-5.8A.76.76 0 0 0 4 2.2z" />
        </svg>
    )
}

function padDotStyle(isActive: boolean, hue: number): React.CSSProperties {
    return {
        position: "relative",
        alignSelf: "center",
        width: 14,
        height: 14,
        borderRadius: "50%",
        background: isActive ? `hsl(${hue}, 85%, 62%)` : "rgba(0,0,0,0.5)",
        boxShadow: isActive
            ? `0 0 10px hsla(${hue}, 85%, 60%, 0.85), inset 0 1px 0 rgba(255,255,255,0.2)`
            : "inset 0 1px 2px rgba(0,0,0,0.6)",
        transition: "background 0.1s ease, box-shadow 0.1s ease",
    }
}

function padLabelStyle(isActive: boolean): React.CSSProperties {
    return {
        position: "relative",
        color: isActive ? "rgba(0,0,0,0.75)" : "rgba(255,255,255,0.55)",
        fontSize: 9,
        fontWeight: 600,
        letterSpacing: 0.3,
        textTransform: "uppercase",
        overflow: "hidden",
        textOverflow: "ellipsis",
        whiteSpace: "nowrap",
        maxWidth: "100%",
    }
}

// single-instrument pads: half the height of the main pads, no
// number/icon, and instead of the main pads' glow-and-border treatment,
// the whole face fills solid with the backlight hue while triggered
function instrumentPadStyle(
    state: "queued" | "playing" | undefined,
    hasAudio: boolean,
    hue: number,
    defaultColor: string,
    isMobile: boolean
): React.CSSProperties {
    const isActive = state === "playing" || state === "queued"
    return {
        position: "relative",
        display: "flex",
        alignItems: "flex-end",
        padding: "6px 8px",
        borderRadius: 4,
        boxSizing: "border-box",
        cursor: hasAudio ? "pointer" : "default",
        outline: "none",
        textAlign: "left",
        fontFamily: "inherit",
        // lightly tinted (30%) by the backlight color when active — see
        // padStyle for the full explanation
        border: isActive
            ? `4px solid color-mix(in srgb, hsl(${hue}, 70%, 62%) 30%, #080808)`
            : "4px solid #080808",
        background: isActive
            ? `radial-gradient(circle at 50% 42%, hsl(${hue}, 88%, 76%) 0%, hsl(${hue}, 82%, 56%) 45%, hsl(${hue}, 72%, 36%) 100%)`
            : hasAudio
              ? `radial-gradient(circle at 50% 42%, color-mix(in srgb, ${defaultColor} 100%, white 22%) 0%, ${defaultColor} 55%, color-mix(in srgb, ${defaultColor} 100%, black 35%) 100%)`
              : "radial-gradient(circle at 50% 42%, #26262a 0%, #1c1c1f 60%, #161618 100%)",
        // rim-light bevel moved to padBevelOverlayStyle so it stays above
        // the pad texture image — see padStyle for the full explanation
        boxShadow: isActive
            ? `0 0 5px hsla(${hue}, 90%, 65%, 0.9), 0 0 18px hsla(${hue}, 85%, 55%, 0.45), inset -1.5px -3px 5px rgba(0,0,0,0.25)`
            : `0 0 10px color-mix(in srgb, ${defaultColor} 55%, transparent), inset -1.5px -3px 5px rgba(0,0,0,0.35)`,
        opacity: hasAudio ? 1 : 0.4,
        animation:
            state === "queued"
                ? "beatpad-pulse 0.5s ease-in-out infinite"
                : "none",
        transition:
            "background 0.15s ease, box-shadow 0.15s ease, border 0.15s ease, filter 0.15s ease",
        // grid items default to an "auto" minimum size on width, and
        // leaving it there lets the item refuse to shrink below that
        // content-driven floor, which is exactly what was blowing the
        // row wider than its 1fr columns should ever allow
        minWidth: 0,
        ...(isMobile
            ? { width: "100%", height: "100%" }
            : // a fixed height (not aspect-ratio) keeps the row's vertical
              // footprint constant regardless of how many pads are
              // configured — with fewer pads the 1fr columns get wider,
              // and tying height to that width via aspect-ratio let a
              // short instrument row blow past the frame's fixed height
              { height: 64 }),
    }
}

function instrumentPadLabelStyle(isActive: boolean): React.CSSProperties {
    return {
        position: "relative",
        color: isActive ? "rgba(0,0,0,0.75)" : "rgba(255,255,255,0.55)",
        fontSize: 9,
        fontWeight: 600,
        letterSpacing: 0.3,
        textTransform: "uppercase",
        overflow: "hidden",
        textOverflow: "ellipsis",
        whiteSpace: "nowrap",
        maxWidth: "100%",
        transition: "color 0.15s ease",
    }
}

